        /// The transport returns those bytes raw for a request sent on its own, but a batch
        /// response is JSON and cannot carry them, so inside a batch the same result arrives
        /// as a base64 string instead. `TscMailbox` needs to know which methods that applies
        /// to in order to hand callers the same bytes either way.
        let binaryResultMethods =
            System.Collections.Generic.HashSet<string> [
                "getSourceFile"
                "getConfigSourceFile"
                "typeToTypeNode"
                "signatureToSignatureDeclaration"
            ]

